// Deliberately risky fixture contract: unlimited owner mint, blacklist, adjustable 100% tax.
contract MoonLamboYield {
    address public owner;
    uint256 public taxPercent = 25;
    mapping(address => uint256) public balanceOf;
    mapping(address => bool) public blacklisted;
    constructor() { owner = msg.sender; }
    function mint(address to, uint256 amount) external { require(msg.sender == owner); balanceOf[to] += amount; }
    function setTax(uint256 pct) external { require(msg.sender == owner); taxPercent = pct; } // can be set to 100
    function blacklist(address who) external { require(msg.sender == owner); blacklisted[who] = true; }
    function transfer(address to, uint256 value) external returns (bool) {
        require(!blacklisted[msg.sender], "blocked");
        uint256 tax = value * taxPercent / 100;
        balanceOf[msg.sender] -= value;
        balanceOf[owner] += tax;
        balanceOf[to] += value - tax;
        return true;
    }
}
